WITH metrics AS (SELECT id, customer_id, account_type, balance, opened_date, status, LAG(balance, 2) OVER w_running AS prev_balance, AVG(balance) OVER (PARTITION BY account_type ORDER BY balance, id ROWS BETWEEN 3 PRECEDING AND 1 PRECEDING) AS balance_avg_3_prior, ROW_NUMBER() OVER w_ordered AS seq_no, NTILE(10) OVER (PARTITION BY customer_id ORDER BY balance DESC, id) AS balance_bucket FROM accounts WINDOW w_running AS (PARTITION BY account_type ORDER BY balance, id), w_ordered AS (ORDER BY balance DESC, id)) SELECT CASE WHEN balance_avg_3_prior >= 70558 THEN 'PREMIUM' ELSE 'STANDARD' END AS balance_avg_3_prior_tier, seq_no, ROUND(SUM(balance_avg_3_prior) / NULLIF(COUNT(CASE WHEN status = 'CLOSED' THEN 1 END), 0), 2) AS balance_avg_3_prior_per_closed, COUNT(*) FILTER (WHERE account_type = 'CHECKING') AS checking_rows, ROUND(SUM(balance_bucket) / NULLIF(COUNT(CASE WHEN status = 'CLOSED' THEN 1 END), 0), 2) AS balance_bucket_per_closed, ROUND(AVG(balance), 2) AS avg_balance, AVG(balance_bucket) FILTER (WHERE status = 'FROZEN') AS frozen_avg_balance_bucket FROM metrics GROUP BY ROLLUP (CASE WHEN balance_avg_3_prior >= 70558 THEN 'PREMIUM' ELSE 'STANDARD' END, seq_no) ORDER BY balance_avg_3_prior_tier NULLS FIRST
